    browser: true,
    node: true,
    jest: true
  }
}

{
  globals: {
    "jQuery": "readonly",
    "$": "readonly"
  }
}

module.exports = {
  rules: {
    "no-console": "error"
  },
  overrides: [{
    files: ["__test__/**/*.js"],
    rules: {
      "no-console": "off"
    }
  }]
}

// .eslintrc.js
module.exports = {
  rules: {
    semi: ['error']
